// Loader for the FRIL tetramer model in public/models/fril-9vbw.json,
// generated by scripts/build-fril-model.py from PDB 9VBW (FRIL from Lablab
// purpureus bound to a Lewis X tetrasaccharide, 2.49 Å X-ray).
//
// Coordinates are in ångströms, centred on the tetramer and rotated onto its
// three 2-fold axes. The four carbohydrate-binding sites sit at roughly
// (±21, ±21, ±30) Å — two facing +z and two facing −z — so **local z is the
// cross-linking axis**: a tetramer bridges two virions along it. The scene
// code relies on that.

import * as THREE from "three";

export type FrilMesh = {
  positions: number[];
  indices: number[];
};

export type FrilSite = {
  sugars: { type: string; pos: [number, number, number] }[];
  links: [number, number][];
};

export type FrilModel = {
  source: string;
  units: string;
  /** Blurred molecular envelope, ~2400 faces. */
  surface: FrilMesh;
  /** Same envelope at ~520 faces, for the wireframe overlay. */
  surfaceLow: FrilMesh;
  /** Cα traces, one flat [x,y,z,…] array per monomer. */
  chains: number[][];
  /** The four bound tetrasaccharides, one per monomer. */
  sites: FrilSite[];
};

export const FRIL_MODEL_URL = "/models/fril-9vbw.json";

export async function loadFrilModel(signal?: AbortSignal): Promise<FrilModel> {
  const res = await fetch(FRIL_MODEL_URL, { signal });
  if (!res.ok) throw new Error(`FRIL model: HTTP ${res.status}`);
  return (await res.json()) as FrilModel;
}

/** Centroid of a bound tetrasaccharide — i.e. where that monomer grips a glycan. */
export function siteCenter(site: FrilSite): THREE.Vector3 {
  const v = new THREE.Vector3();
  for (const s of site.sugars) v.add(new THREE.Vector3(...s.pos));
  return v.divideScalar(site.sugars.length);
}

function toGeometry(mesh: FrilMesh): THREE.BufferGeometry {
  const geom = new THREE.BufferGeometry();
  geom.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(mesh.positions, 3),
  );
  geom.setIndex(mesh.indices);
  return geom;
}

/**
 * Surface geometry scaled so the tetramer's longest axis spans `spanUnits`
 * scene units, with the scale factor returned so binding-site positions can
 * be placed in the same frame.
 */
export function buildSurface(
  model: FrilModel,
  spanUnits: number,
): { geometry: THREE.BufferGeometry; wire: THREE.BufferGeometry; scale: number } {
  const geometry = toGeometry(model.surface);
  geometry.computeBoundingBox();
  const size = new THREE.Vector3();
  geometry.boundingBox!.getSize(size);
  const scale = spanUnits / Math.max(size.x, size.y, size.z);

  geometry.scale(scale, scale, scale);
  geometry.computeVertexNormals();

  const low = toGeometry(model.surfaceLow);
  low.scale(scale, scale, scale);
  const wire = new THREE.WireframeGeometry(low);
  low.dispose();

  return { geometry, wire, scale };
}
